```python
import sys
from collections import defaultdict

def main():
    k = int(sys.stdin.readline())
    counts = defaultdict(int)
    for _ in range(4):
        line = sys.stdin.readline().strip()
        for c in line:
            if c != '.':
                counts[c] += 1
    possible = True
    for t in counts:
        if counts[t] > 2 * k:
            possible = False
            break
    print("YES" if possible else "NO")

if __name__ == "__main__":
    main()
```

